   638	        else
   639	                ret =
   640	                    asn1_decode_simple_der(etype, der, der_size, (const uint8_t**)&str, &str_size);
   641	        if (ret != ASN1_SUCCESS) {
   642	                gnutls_assert();
   643	                ret = _gnutls_asn2err(ret);
   644	                return ret;
   645	        }
   646	
   647	        td.size = str_size;
   648	        td.data = gnutls_malloc(str_size + 1);
   649	        if (td.data == NULL)
   650	                return gnutls_assert_val(GNUTLS_E_MEMORY_ERROR);
   651	
   652	        memcpy(td.data, str, str_size);
   653	        td.data[str_size] = 0;
   654	
   655	        if (allow_ber)
   656	                free(str);
   657	
   658	        ret = make_printable_string(etype, &td, output);
   659	        if (ret == GNUTLS_E_INVALID_REQUEST) {  /* unsupported etype */
   660	                output->data = td.data;
   661	                output->size = td.size;
   662	                ret = 0;
   663	        } else if (ret <= 0) {
   664	                _gnutls_free_datum(&td);
   665	        }
   666	
   667	        /* Refuse to deal with strings containing NULs. */
   668	        if (etype != ASN1_ETYPE_OCTET_STRING) {
   669	                if (output->data)
   670	                        len = strlen((void *) output->data);
   671	                else
   672	                        len = 0;
   673	
   674	                if (len != (size_t) output->size) {
   675	                        _gnutls_free_datum(output);
   676	                        ret = gnutls_assert_val(GNUTLS_E_ASN1_EMBEDDED_NULL_IN_STRING);
   677	                }
   678	        }
   679	
   680	        return ret;
